// ... (keep all the imports and interfaces the same)

export default function UserPage() {
  // ... (keep all the existing state and effect hooks)

  return (
    <div className="min-h-screen bg-gray-50 flex">
      {/* Sidebar */}
      <div className="hidden md:block h-full fixed left-0 top-0 shadow z-30">
        <Sidebar />
      </div>

      {/* Main Content */}
      <main className="flex-1 py-8 px-4 sm:px-6 lg:px-8 md:ml-64">
        <div className="max-w-4xl mx-auto">
          {/* Profile Header */}
          <div className="bg-white rounded-xl shadow-sm overflow-hidden">
            {/* Cover Photo Placeholder */}
            <div className="h-32 bg-gradient-to-r from-blue-500 to-indigo-600"></div>
            
            {/* Profile Info */}
            <div className="px-6 pb-6 relative">
              <div className="flex flex-col sm:flex-row items-start sm:items-end gap-6 -mt-16">
                {/* Profile Picture */}
                <div className="relative">
                  {user.profilePicture ? (
                    <Image
                      src={user.profilePicture}
                      alt="Profile"
                      width={120}
                      height={120}
                      className="rounded-full object-cover border-4 border-white shadow-lg"
                    />
                  ) : (
                    <div className="w-32 h-32 rounded-full bg-gray-200 border-4 border-white shadow-lg flex items-center justify-center">
                      <FaUserCircle className="text-gray-400 text-6xl" />
                    </div>
                  )}
                </div>

                {/* User Details */}
                <div className="flex-1">
                  <div className="flex justify-between items-start">
                    <div>
                      <h1 className="text-2xl font-bold text-gray-900">
                        {user.firstName} {user.lastName || ''}
                      </h1>
                      <div className="flex items-center mt-1 text-gray-600">
                        <FaUniversity className="mr-2 text-gray-500" />
                        <span>{user.university || 'No university specified'}</span>
                      </div>
                    </div>

                    {/* Role Badge */}
                    <span className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-medium ${getRoleColor()}`}>
                      {getRoleIcon()}
                      <span className="ml-1">{user.role?.toLowerCase() || 'user'}</span>
                    </span>
                  </div>

                  {/* Action Buttons */}
                  <div className="flex items-center gap-3 mt-4">
                    {user.canMessage && (
                      <button 
                        onClick={handleMessage}
                        className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors"
                      >
                        <MdEmail />
                        <span>Message</span>
                      </button>
                    )}
                    
                    {user.canFollow && (
                      <button 
                        onClick={handleFollow}
                        className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-colors ${
                          isFollowing 
                            ? 'bg-white border border-gray-300 hover:bg-gray-50' 
                            : 'bg-blue-600 text-white hover:bg-blue-700'
                        }`}
                      >
                        {isFollowing ? (
                          <>
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                              <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                            </svg>
                            <span>Following</span>
                          </>
                        ) : (
                          <>
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                              <path fillRule="evenodd" d="M10 9a3 3 0 100-6 3 3 0 000 6zm-7 9a7 7 0 1114 0H3z" clipRule="evenodd" />
                            </svg>
                            <span>Follow</span>
                          </>
                        )}
                      </button>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Profile Sections */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mt-6">
            {/* Education */}
            <div className="bg-white rounded-xl shadow-sm p-6">
              <div className="flex items-center mb-4">
                <MdSchool className="text-blue-500 text-xl mr-2" />
                <h2 className="text-lg font-semibold text-gray-900">Education</h2>
              </div>
              <div className="space-y-4">
                {user.formation && (
                  <div>
                    <p className="text-sm text-gray-500">Formation</p>
                    <p className="font-medium">{user.formation}</p>
                  </div>
                )}
                {user.degree && (
                  <div>
                    <p className="text-sm text-gray-500">Degree</p>
                    <p className="font-medium">{user.degree}</p>
                  </div>
                )}
              </div>
            </div>

            {/* Professional Info */}
            <div className="bg-white rounded-xl shadow-sm p-6">
              <div className="flex items-center mb-4">
                <FaBriefcase className="text-purple-500 text-xl mr-2" />
                <h2 className="text-lg font-semibold text-gray-900">
                  {user.role === 'PROFESSOR' ? 'Teaching' : 'Professional'} Info
                </h2>
              </div>
              <div className="space-y-4">
                {user.occupation && (
                  <div>
                    <p className="text-sm text-gray-500">Occupation</p>
                    <p className="font-medium">{user.occupation}</p>
                  </div>
                )}
                {user.subject && (
                  <div>
                    <p className="text-sm text-gray-500">Subject</p>
                    <p className="font-medium">{user.subject}</p>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Posts Section */}
          <div className="mt-8">
            <div className="flex border-b border-gray-200">
              <button
                onClick={() => setSelectedTab('posts')}
                className={`px-4 py-2 font-medium text-sm ${
                  selectedTab === 'posts'
                    ? 'border-b-2 border-blue-500 text-blue-600'
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                Posts
              </button>
              {session?.user?.id === user.id && (
                <button
                  onClick={() => setSelectedTab('saved')}
                  className={`px-4 py-2 font-medium text-sm ${
                    selectedTab === 'saved'
                      ? 'border-b-2 border-blue-500 text-blue-600'
                      : 'text-gray-500 hover:text-gray-700'
                  }`}
                >
                  Saved
                </button>
              )}
            </div>

            <div className="mt-6">
              {selectedTab === 'posts' ? (
                <div className="space-y-6">
                  {posts.length > 0 ? (
                    posts.map(post => session && (
                      <PostCard
                        key={post.id}
                        post={post}
                        session={session}
                        isPending={false}
                        saved={false}
                        onToggleSave={handleToggleSave}
                        onDelete={handleDeletePost}
                      />
                    ))
                  ) : (
                    <div className="bg-white rounded-xl shadow-sm p-8 text-center">
                      <div className="mx-auto w-24 h-24 bg-gray-100 rounded-full flex items-center justify-center mb-4">
                        <FaGraduationCap className="text-gray-400 text-3xl" />
                      </div>
                      <h3 className="text-lg font-medium text-gray-900 mb-2">No posts yet</h3>
                      <p className="text-gray-500">
                        This user hasn't shared any posts yet
                      </p>
                    </div>
                  )}
                </div>
              ) : (
                <div className="bg-white rounded-xl shadow-sm p-8 text-center">
                  <div className="mx-auto w-24 h-24 bg-gray-100 rounded-full flex items-center justify-center mb-4">
                    <FaBookmark className="text-gray-400 text-3xl" />
                  </div>
                  <h3 className="text-lg font-medium text-gray-900">Saved posts</h3>
                  <p className="text-gray-500 mt-2">
                    Your saved posts will appear here
                  </p>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Chat box - desktop view */}
        {showChat && convoId && session && (
          <div className="fixed bottom-0 right-0 w-96 h-[500px] bg-white shadow-lg rounded-t-lg border border-gray-200 z-10">
            <div className="flex justify-between items-center bg-blue-600 text-white p-3 rounded-t-lg">
              <h3 className="font-medium">Chat with {user.firstName}</h3>
              <button 
                onClick={() => setShowChat(false)}
                className="text-white hover:text-gray-200"
              >
                <FaTimes />
              </button>
            </div>
            <ChatBox convoId={convoId} currentUserId={session.user.id} />
          </div>
        )}
      </main>
    </div>
  );
}